<?php $root_id = $section_anchor ?: $section_instance; $title_id = platejka_section_dom_id( $section_instance, 'title' ); $items = is_array( $section_data['items'] ?? null ) ? $section_data['items'] : array(); ?>
<section class="call" id="<?php echo esc_attr( $root_id ); ?>" data-call aria-label="<?php echo esc_attr( wp_strip_all_tags( (string) ( $section_data['title'] ?? '' ) ) ); ?>"><div class="container"><div class="call__panel call__row"><div class="call__layout">
  <div class="call__column"><?php echo platejka_section_heading( array( 'text' => $section_data['title'] ?? '', 'accent' => $section_data['title_accent'] ?? '', 'decorative' => ! empty( $section_data['title_accent'] ) ), 'call__title' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><div class="call__description"><?php echo wp_kses_post( $section_data['description'] ?? '' ); ?></div><ul class="list-reset hero__trust call__trust"><?php foreach ( $items as $item ) : ?><li class="hero__trust-card" data-call-card><?php echo platejka_section_image( $item['image'] ?? 0, 'medium', array( 'loading' => 'lazy' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><p class="hero__trust-title"><?php echo esc_html( $item['title'] ?? '' ); ?></p><div class="hero__trust-caption"><?php echo wp_kses_post( $item['text'] ?? '' ); ?></div><?php if ( ! empty( $item['value'] ) ) : ?><strong><?php echo esc_html( $item['value'] ); ?></strong><?php endif; ?></li><?php endforeach; ?></ul></div>
  <div class="call__form" data-call-form><?php echo platejka_cf7_form( $section_data['form'] ?? 0 ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></div>
</div></div></div></section>
